    // ── COMPUTED ──
    private List<HikvisionDevice> FilteredCameras
    {
        get
        {
            if (string.IsNullOrWhiteSpace(_camSearch)) return _cameras;
            var kw = _camSearch.Trim().ToLower();
            return _cameras.Where(c =>
                (c.devName?.ToLower().Contains(kw) ?? false) ||
                (c.EhomeParams?.EhomeID?.ToLower().Contains(kw) ?? false) ||
                (c.devSerial?.ToLower().Contains(kw) ?? false) ||
                (c.devMode?.ToLower().Contains(kw) ?? false)
            ).ToList();
        }
    }

