    protected override async Task OnInitializedAsync()
    {
        _maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JSRuntime);
        await Task.WhenAll(LoadTruong(), LoadCauHinh());
        _ = LoadCameras();
    }

    // ══════════════════════════════════════
    // THÔNG TIN TRƯỜNG
