    private async Task LoadTruong()
    {
        if (string.IsNullOrEmpty(_maTruongBo)) return;
        _loadingTruong = true; StateHasChanged();
        try { _truong = await TruongService.hThongTinTruongByID(_maTruongBo); }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error"); }
        finally { _loadingTruong = false; StateHasChanged(); }
    }

    private async Task SaveTruong()
    {
        if (_truong == null) return;
        _savingTruong = true; StateHasChanged();
        try
        {
            await TruongService.hUpsertThongTinTruong(_truong);
            await ShowToast("Lưu thông tin trường thành công!", "success");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error"); }
        finally { _savingTruong = false; StateHasChanged(); }
    }

    private string GetLogoUrl()
    {
        if (string.IsNullOrWhiteSpace(_maTruongBo)) return "/image/avtmacdinh.jpg";
        // Luôn dùng đường dẫn local: /image/logo/{maTruongBo}.jpg
        // Thêm query-string để bust cache sau khi upload mới
        var logoFile = $"/image/logo/{_maTruongBo}.jpg";
        return _logoVersion > 0 ? $"{logoFile}?v={_logoVersion}" : logoFile;
    }

    // ── LOGO MODAL ──
    private void OpenLogoModal()
    {
        _logoPreviewUrl = null; _logoError = ""; _selectedLogoFile = null;
        _showLogoModal = true;
    }
    private void CloseLogoModal() => _showLogoModal = false;

    private async Task OnLogoSelected(InputFileChangeEventArgs e)
    {
        _logoError = ""; _selectedLogoFile = null; _logoPreviewUrl = null;
        var file = e.File;
        var ext = Path.GetExtension(file.Name).ToLowerInvariant();
        if (ext != ".jpg" && ext != ".jpeg") { _logoError = "Chỉ chấp nhận file JPG/JPEG!"; return; }
        const long maxBytes = 200 * 1024;
        if (file.Size > maxBytes) { _logoError = $"File quá lớn ({file.Size / 1024} KB). Tối đa 200 KB."; return; }
        _selectedLogoFile = file;
        try
        {
            await using var stream = file.OpenReadStream(maxBytes);
            using var ms = new MemoryStream();
            await stream.CopyToAsync(ms);
            _logoPreviewUrl = $"data:image/jpeg;base64,{Convert.ToBase64String(ms.ToArray())}";
        }
        catch (Exception ex) { _logoError = "Đã xảy ra lỗi, vui lòng thử lại!"; }
    }

    private async Task SaveLogo()
    {
        if (_truong == null || _selectedLogoFile == null) return;
        _savingLogo = true; StateHasChanged();
        try
        {
            // ── Xác định thư mục lưu ảnh ──
            var logoDir = Path.Combine(WebHostEnv.WebRootPath, "image", "logo");
            Directory.CreateDirectory(logoDir); // tạo nếu chưa có

            var fileName = $"{_maTruongBo}.jpg";
            var filePath = Path.Combine(logoDir, fileName);

            // ── Đọc stream & ghi file ──
            const long maxBytes = 200 * 1024;
            await using var readStream = _selectedLogoFile.OpenReadStream(maxBytes);
            await using var fs = new FileStream(filePath, FileMode.Create, FileAccess.Write);
            await readStream.CopyToAsync(fs);

            // ── Lưu tên file vào DB (chỉ lưu tên, không lưu full path) ──
            _truong.LogoTruong = fileName;
            await TruongService.hUpsertThongTinTruong(_truong);

            // ── Bust cache để ảnh mới hiển thị ngay ──
            _logoVersion = DateTime.Now.Ticks;

            CloseLogoModal();
            await ShowToast("Cập nhật logo thành công!", "success");
        }
        catch (Exception ex) { _logoError = "Đã xảy ra lỗi, vui lòng thử lại!"; }
        finally { _savingLogo = false; StateHasChanged(); }
    }

