        _loadingCauHinh = true; StateHasChanged();
        try { _cauHinh = await DiemDanhServices.hGetCauHinhDiemDanhAsync(); }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error"); }
        finally { _loadingCauHinh = false; StateHasChanged(); }
    }

    private async Task SaveCauHinh()
    {
        if (_cauHinh == null) return;
        _savingCauHinh = true; StateHasChanged();
        try
        {
            await DiemDanhServices.hUpsertCauHinhDiemDanhAsync(_cauHinh);
            await ShowToast("Lưu cấu hình điểm danh thành công!", "success");
        }
        catch (Exception ex) { Console.WriteLine(ex); await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error"); }
        finally { _savingCauHinh = false; StateHasChanged(); }
    }

