        _loadingCam = true; _camError = ""; StateHasChanged();
        try { _cameras = await GetHikvisionDevicesAsync(); }
        catch (Exception ex) { _camError = ex.Message; }
        finally { _loadingCam = false; StateHasChanged(); }
    }

    private void OpenCamDetail(HikvisionDevice cam)
    {
        _selectedCam = cam; _showCamDetail = true;
    }

    private async Task<List<HikvisionDevice>> GetHikvisionDevicesAsync()
    {
        var reqBody = new
        {
            SearchDescription = new
            {
                position = 0, maxResult = 100,
                Filter = new
                {
                    key = HikDeviceKey, devType = "",
                    protocolType =  new List<string> { HikProtocolType },
                    devStatus = new List<string> { "online", "offline" }
                }
            }
        };
        var handler = new HttpClientHandler
        {
            Credentials = new System.Net.NetworkCredential(HikUsername, HikPassword)
        };
        using var client = new HttpClient(handler) { Timeout = TimeSpan.FromSeconds(30) };
        var content = new StringContent(JsonConvert.SerializeObject(reqBody), Encoding.UTF8, "application/json");
        var resp = await client.PostAsync($"{HikBaseUrl}/ISAPI/ContentMgmt/DeviceMgmt/deviceList?format=json", content);
        if (!resp.IsSuccessStatusCode) throw new Exception($"API lỗi: {resp.StatusCode}");
        var json = await resp.Content.ReadAsStringAsync();
        var result = JsonConvert.DeserializeObject<HikvisionDeviceListResponse>(json);
        return result?.SearchResult?.MatchList?.Select(m => m.Device).Where(d => d != null).ToList()
               ?? new List<HikvisionDevice>();
    }

    // ══════════════════════════════════════
    // TOAST
    // ══════════════════════════════════════
    private async Task ShowToast(string msg, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts = new System.Threading.CancellationTokenSource();
        _toastMsg = msg; _toastType = type; _toastVisible = true; StateHasChanged();
        try { await Task.Delay(3500, _toastCts.Token); _toastVisible = false; StateHasChanged(); }
        catch (TaskCanceledException) { }
    }

