        public string devStatus { get; set; } = "";
        public string protocolType { get; set; } = "";
        public int videoChannelNum { get; set; }
        public EhomeParams? EhomeParams { get; set; }
    }
    public class EhomeParams { public string? EhomeID { get; set; } }
    public class HikvisionDeviceListResponse { public SearchResult? SearchResult { get; set; } }
